-- Cari hesap kodu alanı + Excel listesi (CARİ HESAPLAR)
-- Supabase SQL Editor'de bir kez çalıştırın.

ALTER TABLE customers ADD COLUMN IF NOT EXISTS code TEXT;

UPDATE customers
SET code = trim(substring(note from 'Kod:\s*([^|]+)'))
WHERE code IS NULL AND note ~ '^Kod:';

CREATE UNIQUE INDEX IF NOT EXISTS customers_code_key ON customers (code);
CREATE INDEX IF NOT EXISTS idx_customers_code ON customers (code);

ON CONFLICT (code) DO UPDATE
SET name = EXCLUDED.name,
    note = EXCLUDED.note;
